document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&!card.dataset.category.split(' ').includes(button.dataset.filter)})}));
document.querySelectorAll('[data-trip]').forEach(a=>a.addEventListener('click',()=>{document.getElementById('trip').value=a.dataset.trip}));
document.getElementById('trip-form').addEventListener('submit',event=>{event.preventDefault();const d=new FormData(event.currentTarget);const body=`Hi Tomasz,\n\nI'd like to enquire about: ${d.get('trip')}\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nNumber of guests: ${d.get('people')||'To be arranged'}\n\n${d.get('message')}\n\nBest wishes,\n${d.get('name')}`;location.href='mailto:oczymmarzysz@icloud.com?subject='+encodeURIComponent('Private tour enquiry — '+d.get('trip'))+'&body='+encodeURIComponent(body);document.getElementById('form-status').textContent='Your email draft is ready. Please send it in your email app. If no app opens, write directly to oczymmarzysz@icloud.com.'});
document.getElementById('year').textContent=new Date().getFullYear();
